import{_ as i,o as a,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2019-03-26:: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-03-26:: Crimson SeaStor OSD Weekly Meeting","date":"2019-03-26T00:00:00.000Z","updated":"2019-04-15T00:00:00.000Z","tags":["Ceph","Crimson OSD","Performance Optimization","Distributed Storage","OSD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-03-26_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-03-26_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),t={name:"posts/2019/2019-03-26_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function o(n,e,s,p,S,c){return a(),l("div",null,[...e[0]||(e[0]=[r('<h3 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h3><p>在2019年3月26日的Ceph Crimson SeaStor OSD每周会议上，研发人员和内容审核专家讨论了Ceph分布式存储系统性能优化与Crimson OSD项目的进展。以下是对会议内容的总结：</p><h4 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h4><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>[请填写会议时间]</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><p>[请填写参会人员名单]</p><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>Ceph 分布式存储系统性能优化与 crimson OSD 项目的进展讨论</p><h4 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h4><ul><li><p><strong>Crimson OSD 项目</strong>：</p><ul><li>已完成初步的 crimson OSD 实现，但部分功能尚未完善。</li><li>性能测试显示，在某些场景下，crimson OSD 的性能优于经典 OSD，但需要进一步优化。</li><li>优化方向包括减少线程切换，提高指令缓存命中率，优化内存使用。</li><li>下一步计划是完成 crimson OSD 的全部功能，进行更全面的性能测试，并与经典 OSD 进行公平的比较。</li></ul></li><li><p><strong>经典 OSD 优化</strong>：</p><ul><li>优化目标为提高 CPU 使用效率和减少内存占用。</li><li>使用 perf stat 工具进行性能分析，观察 CPU 使用率、内存占用等指标。</li><li>下一步计划是调整 placement group 的数量，提高经典 OSD 的并行处理能力。</li></ul></li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题： <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题：&quot;">​</a></h4><ul><li><p><strong>Crimson OSD 性能优化</strong>：</p><ul><li>如何减少线程切换，提高指令缓存命中率。</li><li>如何优化内存使用，减少内存占用。</li><li>如何与经典 OSD 进行公平的比较。</li></ul></li><li><p><strong>经典 OSD 优化</strong>：</p><ul><li>如何提高 CPU 使用效率。</li><li>如何减少内存占用。</li><li>如何调整 placement group 的数量。</li></ul></li></ul><h4 id="决定的事项" tabindex="-1">决定的事项： <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项：&quot;">​</a></h4><ul><li>完成 crimson OSD 的全部功能。</li><li>进行更全面的性能测试，并与经典 OSD 进行公平的比较。</li><li>调整 classic OSD 的 placement group 数量，提高其并行处理能力。</li><li>使用 perf stat 工具进行性能分析，观察 CPU 使用率、内存占用等指标。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>Crimson OSD 项目负责人：完成 crimson OSD 的全部功能，并进行性能测试。</li><li>Classic OSD 项目负责人：调整 classic OSD 的 placement group 数量，并进行性能测试。</li><li>全体成员：关注 crimson OSD 和 classic OSD 的性能优化工作，提供反馈和建议。</li></ul><p>会议中，与会者还讨论了以下关键点：</p><ul><li>如何通过优化 crimson OSD 的解码阶段来提高性能。</li><li>如何使用 perf stat 工具进行性能分析，并如何使用它来比较 crimson OSD 和经典 OSD 的性能。</li><li>如何通过调整 placement group 的数量来优化经典 OSD 的性能。</li><li>如何在 crimson OSD 中使用应用程序队列来提高性能。</li></ul><p>会议强调了性能优化和 crimson OSD 项目的进展对 Ceph 分布式存储系统的重要性。与会者决定采取进一步的行动，以提高 Ceph 的性能和可靠性。</p>',20)])])}const u=i(t,[["render",o]]);export{_ as __pageData,u as default};
